#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <inttypes.h>
#include "libavfilter/avfilter.h"
#include "libavfilter/avfilter_internal.h"
#include "libavfilter/buffersrc.h"
#include "libavfilter/buffersink.h"
#include "libavutil/log.h"
#include "libavutil/pixfmt.h"
static void queues(AVFilterGraph *g){putchar('[');for(unsigned i=0;i<g->nb_filters;i++){if(i)putchar(',');putchar('[');int first=1;for(AVFilterCommand *c=fffilterctx(g->filters[i])->command_queue;c;c=c->next){uint64_t bits;memcpy(&bits,&c->time,8);if(!first)putchar(',');first=0;printf("{\"name\":\"%s\",\"argument\":\"%s\",\"timeBits\":\"%016"PRIx64"\",\"flags\":%d}",c->command,c->arg,bits,c->flags);}putchar(']');}putchar(']');}
int main(int argc,char **argv){if(argc!=2)return 2;av_log_set_level(AV_LOG_QUIET);AVFilterGraph *g=avfilter_graph_alloc();g->nb_threads=1;AVFilterInOut *ins=NULL,*outs=NULL;AVFilterContext *src=NULL,*sink=NULL;if(avfilter_graph_parse2(g,"setpts=PTS",&ins,&outs)<0||!ins||!outs)return 3;char args[256];snprintf(args,sizeof(args),"video_size=1x1:pix_fmt=8:time_base=%s:frame_rate=25/1",argv[1]);if(avfilter_graph_create_filter(&src,avfilter_get_by_name("buffer"),"source0",args,NULL,g)<0||avfilter_link(src,0,ins->filter_ctx,ins->pad_idx)<0)return 4;if(avfilter_graph_create_filter(&sink,avfilter_get_by_name("buffersink"),"sink0",NULL,NULL,g)<0||avfilter_link(outs->filter_ctx,outs->pad_idx,sink,0)<0||avfilter_graph_config(g,NULL)<0)return 5;avfilter_inout_free(&ins);avfilter_inout_free(&outs);if(g->nb_filters!=3)return 6;int n;if(scanf("%d",&n)!=1||n<0||n>1024)return 7;putchar('[');for(int i=0;i<n;i++){char op;if(scanf(" %c",&op)!=1)return 8;int ret;if(op=='q'){int node,flags;double time;char name[4097],argument[4097];if(scanf("%d %d %lf %4096s %4096s",&node,&flags,&time,name,argument)!=5||node< -1||node>2)return 9;if(!strcmp(argument,"<empty>"))argument[0]=0;ret=avfilter_graph_queue_command(g,node<0?"all":g->filters[node]->name,name,argument,flags,time);}else if(op=='f'){int64_t pts;if(scanf("%"SCNd64,&pts)!=1)return 10;AVFrame *frame=av_frame_alloc();frame->width=frame->height=1;frame->format=AV_PIX_FMT_GRAY8;frame->pts=pts;frame->duration=1;if(av_frame_get_buffer(frame,32)<0)return 11;frame->data[0][0]=7;ret=av_buffersrc_add_frame_flags(src,frame,AV_BUFFERSRC_FLAG_PUSH);av_frame_unref(frame);if(ret>=0&&av_buffersink_get_frame_flags(sink,frame,AV_BUFFERSINK_FLAG_NO_REQUEST)!=0)return 12;av_frame_free(&frame);}else if(op=='e'){ret=av_buffersrc_close(src,4,AV_BUFFERSRC_FLAG_PUSH);}else return 13;if(i)putchar(',');printf("{\"result\":%d,\"queues\":",ret);queues(g);putchar('}');}puts("]");avfilter_graph_free(&g);return 0;}
